from dataclasses import dataclass
from typing import Generic, TypeVar
import math

T = TypeVar('T')

class Option(Generic[T]):
    pass

@dataclass
class Some(Option[T]):
    value: T

class Nothing(Option[T]):
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

def safe_sqrt(n: float) -> Option[float]:
    if n >= 0:
        return Some(math.sqrt(n))
    else:
        return Nothing()

def print_result(result: Option[float]) -> None:
    if isinstance(result, Some):
        print(f"Root: {result.value}")
    elif isinstance(result, Nothing):
        print("Error: Negative input")

if __name__ == "__main__":
    print_result(safe_sqrt(16.0))
    print_result(safe_sqrt(-4.0))

