def isBalanced(s: str) -> bool:
    """
    Checks if parentheses in a string are balanced.
    Uses a counter: increment for '(', decrement for ')'.
    Balanced if counter never goes negative and ends at zero.
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        # If balance goes negative, a closing parenthesis appeared before an opening one
        if balance < 0:
            return False

    # For the parentheses to be balanced, the final count must be zero
    return balance == 0

if __name__ == "__main__":
    test_strings = [
        "(())",
        "(()",
        "())()",
        "()(())"
    ]

    for s in test_strings:
        print(str(isBalanced(s)).lower())

