import std/string (split, stringToInt, trim)
import std/list (foldl)
import std/env (getArgs)
import std/option (Some, None)

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      let sum = foldl(func(acc: int, line: string) -> int {
        let trimmed = trim(line);
        match stringToInt(trimmed) {
          Some(n) => acc + n,
          None => acc
        }
      }, 0, lines);
      println(show(sum))
    },
    _ => println("Usage: program <filename>")
  }
}

