import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <filename>")
        sys.exit(1)

    filename = sys.argv[1]
    total_sum = 0.0
    line_number = 0

    try:
        with open(filename, 'r') as f:
            for line in f:
                line_number += 1
                stripped_line = line.strip()
                if not stripped_line:  # Skip empty lines
                    continue
                try:
                    number = float(stripped_line)
                    total_sum += number
                except ValueError:
                    print(f"Warning: Could not parse '{stripped_line}' as a number on line {line_number}. Skipping this line.")
    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    print(total_sum)

if __name__ == "__main__":
    main()

