export type BST = Leaf | Node(BST, int, BST)

export pure func insert(tree: BST, value: int) -> BST ! {}
requires { true }
ensures { contains(result, value) }
{
  match tree {
    Leaf => Node(Leaf, value, Leaf),
    Node(left, root, right) =>
      if value < root then Node(insert(left, value), root, right)
      else if value > root then Node(left, root, insert(right, value))
      else tree
  }
}

export pure func contains(tree: BST, value: int) -> bool ! {}
requires { true }
ensures { true }
{
  match tree {
    Leaf => false,
    Node(left, root, right) =>
      if value == root then true
      else if value < root then contains(left, value)
      else contains(right, value)
  }
}

export pure func size(tree: BST) -> int ! {}
requires { true }
ensures { result >= 0 }
{
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }
}

export pure func isBST(tree: BST, minVal: int, maxVal: int) -> bool ! {}
requires { minVal <= maxVal }
ensures { result == validateBST(tree, minVal, maxVal) }
{
  match tree {
    Leaf => true,
    Node(left, root, right) =>
      root > minVal && root < maxVal &&
      isBST(left, minVal, root) &&
      isBST(right, root, maxVal)
  }
}

pure func validateBST(tree: BST, minVal: int, maxVal: int) -> bool ! {}
requires { minVal <= maxVal }
ensures { true }
{
  match tree {
    Leaf => true,
    Node(left, root, right) =>
      root > minVal && root < maxVal &&
      validateBST(left, minVal, root) &&
      validateBST(right, root, maxVal)
  }
}

export pure func insertPreservesBST(value: int) -> bool ! {}
requires { true }
ensures { result == true }
{
  let tree1 = insert(Leaf, 5);
  let tree2 = insert(tree1, 3);
  let tree3 = insert(tree2, 7);
  let tree4 = insert(tree3, value);
  isBST(tree4, -999999, 999999)
}

export pure func insertThenFind(value: int) -> bool ! {}
requires { true }
ensures { result == true }
{
  let tree1 = insert(Leaf, 5);
  let tree2 = insert(tree1, 3);
  let tree3 = insert(tree2, 7);
  let tree4 = insert(tree3, value);
  contains(tree4, value)
}

export func main() -> () ! {IO}
{
  let tree1 = insert(Leaf, 5);
  let tree2 = insert(tree1, 3);
  let tree3 = insert(tree2, 7);

  println(show(size(tree3)));
  println(show(contains(tree3, 3)));
  println(show(contains(tree3, 4)));
  println(show(isBST(tree3, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

