class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left if left is not None else Leaf
        self.right = right if right is not None else Leaf

class _Leaf:
    pass

Leaf = _Leaf()

def insert(tree, value):
    if tree is Leaf:
        return Node(value)
    if value < tree.value:
        tree.left = insert(tree.left, value)
    elif value > tree.value:
        tree.right = insert(tree.right, value)
    # If value == tree.value, do nothing (duplicates not allowed)
    return tree

def contains(tree, value):
    if tree is Leaf:
        return False
    if value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    else: # value > tree.value
        return contains(tree.right, value)

def isBST(tree, min_bound, max_bound):
    if tree is Leaf:
        return True
    if not (min_bound < tree.value < max_bound):
        return False
    return isBST(tree.left, min_bound, tree.value) and \
           isBST(tree.right, tree.value, max_bound)

def size(tree):
    if tree is Leaf:
        return 0
    return 1 + size(tree.left) + size(tree.right)

