module benchmark/solution

import std/io (println)

-- 2x2 determinant: | a b |
--                  | c d |
-- det = ad - bc
export func det2(a: int, b: int, c: int, d: int) -> int ! {} {
  a * d - b * c
}

-- 3x3 determinant using cofactor expansion along first row
-- | a b c |
-- | d e f |
-- | g h i |
-- det = a(ei - fh) - b(di - fg) + c(dh - eg)
export func det3(a: int, b: int, c: int, d: int, e: int, f: int, g: int, h: int, i: int) -> int ! {} {
  a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

-- Identity matrix determinant should be 1
export func identityDet() -> int ! {} {
  det3(1, 0, 0, 0, 1, 0, 0, 0, 1)
}

-- Zero row determinant should be 0
export func zeroRowDet(a: int, b: int, c: int, d: int, e: int, f: int) -> int ! {} {
  det3(a, b, c, d, e, f, 0, 0, 0)
}

export func main() -> () ! {IO} {
  println(show(det2(3, 8, 4, 6)));
  println(show(det3(6, 1, 1, 4, -2, 5, 2, 8, 7)));
  println(show(det3(1, 0, 0, 0, 1, 0, 0, 0, 1)));
  println(show(identityDet()));
  println(show(zeroRowDet(3, 5, 7, 2, 4, 6)))
}

