import math

def det2(a, b, c, d):
    return a * d - b * c

def det3(a, b, c, d, e, f, g, h, i):
    # Using Sarrus's rule for 3x3 determinant
    # a(ei - fh) - b(di - fg) + c(dh - eg)
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)

def identityDet():
    # Determinant of the 3x3 identity matrix should be 1
    return det3(1, 0, 0, 0, 1, 0, 0, 0, 1)

def zeroRowDet(a, b, c, d, e, f):
    # This function is meant to demonstrate a property of determinants:
    # if a row (or column) is all zeros, the determinant is zero.
    # We'll construct a 3x3 matrix with a row of zeros.
    # The input a,b,c,d,e,f will form the other two rows.
    # Let's make the second row all zeros for simplicity.
    return det3(a, b, c, 0, 0, 0, d, e, f)

if __name__ == "__main__":
    print(det2(3, 8, 4, 6))
    print(det3(6, 1, 1, 4, -2, 5, 2, 8, 7))
    print(det3(1, 0, 0, 0, 1, 0, 0, 0, 1))
    print(identityDet())
    print(zeroRowDet(3, 5, 7, 2, 4, 6))

