module benchmark/solution

import std/string (chars, length, substring, stringToInt)
import std/list (length as listLength, foldl)
import std/option (Option, Some, None)

pure func encode(s: string) -> string {
  let cs = chars(s);
  encodeChars(cs)
}

pure func encodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    c :: rest => {
      let counted = countRun(c, rest, 1);
      match counted {
        (n, remaining) => show(n) ++ c ++ encodeChars(remaining)
      }
    }
  }

pure func countRun(c: string, cs: [string], acc: int) -> (int, [string]) =
  match cs {
    [] => (acc, []),
    x :: rest => if x == c then countRun(c, rest, acc + 1) else (acc, cs)
  }

pure func decode(s: string) -> string {
  let cs = chars(s);
  decodeChars(cs)
}

pure func decodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    _ => {
      let parsed = parseNum(cs, "");
      match parsed {
        (numStr, rest) => match rest {
          [] => "",
          ch :: remaining => {
            match stringToInt(numStr) {
              Some(n) => repeatStr(ch, n) ++ decodeChars(remaining),
              None => ""
            }
          }
        }
      }
    }
  }

pure func parseNum(cs: [string], acc: string) -> (string, [string]) =
  match cs {
    [] => (acc, []),
    c :: rest => if isDigit(c) then parseNum(rest, acc ++ c) else (acc, cs)
  }

pure func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

pure func repeatStr(s: string, n: int) -> string =
  if n <= 0 then "" else s ++ repeatStr(s, n - 1)

pure func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

pure func singleCharEncode(c: string) -> bool =
  encode(c) == "1" ++ c

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(show(singleCharEncode("q")))
}

module benchmark/solution

import std/string (length, substring)
import std/option (Option, Some, None)

pure func toRoman(n: int) -> string
requires { n >= 1, n <= 3999 }
ensures { length(result) > 0 }
{
  if n >= 1000 then "M" ++ toRoman(n - 1000)
  else if n >= 900 then "CM" ++ toRoman(n - 900)
  else if n >= 500 then "D" ++ toRoman(n - 500)
  else if n >= 400 then "CD" ++ toRoman(n - 400)
  else if n >= 100 then "C" ++ toRoman(n - 100)
  else if n >= 90 then "XC" ++ toRoman(n - 90)
  else if n >= 50 then "L" ++ toRoman(n - 50)
  else if n >= 40 then "XL" ++ toRoman(n - 40)
  else if n >= 10 then "X" ++ toRoman(n - 10)
  else if n >= 9 then "IX"
  else if n >= 5 then "V" ++ toRoman(n - 5)
  else if n >= 4 then "IV"
  else if n >= 1 then "I" ++ toRoman(n - 1)
  else ""
}

func fromRomanHelper(s: string, pos: int, acc: int) -> int {
  if pos >= length(s) then acc
  else {
    let len = length(s);
    let twoChar = if pos + 2 <= len then substring(s, pos, pos + 2) else "";
    let oneChar = substring(s, pos, pos + 1);

    if twoChar == "CM" then fromRomanHelper(s, pos + 2, acc + 900)
    else if twoChar == "CD" then fromRomanHelper(s, pos + 2, acc + 400)
    else if twoChar == "XC" then fromRomanHelper(s, pos + 2, acc + 90)
    else if twoChar == "XL" then fromRomanHelper(s, pos + 2, acc + 40)
    else if twoChar == "IX" then fromRomanHelper(s, pos + 2, acc + 9)
    else if twoChar == "IV" then fromRomanHelper(s, pos + 2, acc + 4)
    else if oneChar == "M" then fromRomanHelper(s, pos + 1, acc + 1000)
    else if oneChar == "D" then fromRomanHelper(s, pos + 1, acc + 500)
    else if oneChar == "C" then fromRomanHelper(s, pos + 1, acc + 100)
    else if oneChar == "L" then fromRomanHelper(s, pos + 1, acc + 50)
    else if oneChar == "X" then fromRomanHelper(s, pos + 1, acc + 10)
    else if oneChar == "V" then fromRomanHelper(s, pos + 1, acc + 5)
    else if oneChar == "I" then fromRomanHelper(s, pos + 1, acc + 1)
    else acc
  }
}

func fromRoman(s: string) -> int {
  fromRomanHelper(s, 0, 0)
}

func roundtrip(n: int) -> bool {
  let roman = toRoman(n);
  let back = fromRoman(roman);
  back == n
}

func distinctEncoding(a: int, b: int) -> bool {
  let ra = toRoman(a);
  let rb = toRoman(b);
  if a == b then ra == rb else ra != rb
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

