module benchmark/solution

type SortedSet = SNil | SCons(int, SortedSet)

pure func sLength(s: SortedSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

pure func isSorted(s: SortedSet) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

pure func sMerge(a: SortedSet, b: SortedSet) -> SortedSet =
  match a {
    SNil => b,
    SCons(x, restA) => match b {
      SNil => a,
      SCons(y, restB) =>
        if x < y then SCons(x, sMerge(restA, b))
        else if x == y then SCons(x, sMerge(restA, restB))
        else SCons(y, sMerge(a, restB))
    }
  }

pure func sIntersect(a: SortedSet, b: SortedSet) -> SortedSet =
  match a {
    SNil => SNil,
    SCons(x, restA) => match b {
      SNil => SNil,
      SCons(y, restB) =>
        if x == y then SCons(x, sIntersect(restA, restB))
        else if x < y then sIntersect(restA, b)
        else sIntersect(a, restB)
    }
  }

pure func toStr(s: SortedSet) -> string =
  match s {
    SNil => "{}",
    SCons(x, rest) => "{" ++ toStrInner(SCons(x, rest)) ++ "}"
  }

pure func toStrInner(s: SortedSet) -> string =
  match s {
