func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

-- Helper to get neighbors from adjacency list
func getNeighbors(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    (n, neighbors) :: rest => if n == node then neighbors else getNeighbors(node, rest)
  }

-- BFS implementation using queue
func bfsHelper(queue: [int], visited: [int], graph: [(int, [int])], result: [int]) -> [int] =
  match queue {
    [] => result,
    node :: restQueue => {
      let newVisited = node :: visited;
      let neighbors = getNeighbors(node, graph);
      let unvisitedNeighbors = filter(func(n: int) -> bool { not contains(n, newVisited) }, neighbors);
      let newQueue = concat(restQueue, unvisitedNeighbors);
      bfsHelper(newQueue, newVisited, graph, concat(result, [node]))
    }
  }

-- Main BFS function
