def contains(item, collection):
    return item in collection

def enqueue(item, queue_list):
    queue_list.append(item)

def bfs(graph_adj_list, start_node):
    graph_dict = {node: neighbors for node, neighbors in graph_adj_list}
    visited_order = []
    queue = []
    seen = []

    enqueue(start_node, queue)
    enqueue(start_node, seen)

    while queue:
        current_node = queue.pop(0)
        visited_order.append(current_node)

        neighbors = graph_dict.get(current_node, [])

        for neighbor in neighbors:
            if not contains(neighbor, seen):
                enqueue(neighbor, queue)
                enqueue(neighbor, seen)
    return visited_order

if __name__ == "__main__":
    graph = [
