type Term = TVar(string) | TLam(string, Term) | TApp(Term, Term)

func subst(term: Term, v: string, replacement: Term) -> Term =
  match term {
    TVar(name) => if name == v then replacement else TVar(name),
    TLam(param, body) => if param == v then TLam(param, body) else TLam(param, subst(body, v, replacement)),
    TApp(f, arg) => TApp(subst(f, v, replacement), subst(arg, v, replacement))
  }

func eval(term: Term) -> Term =
  match term {
    TVar(name) => TVar(name),
    TLam(param, body) => TLam(param, body),
    TApp(f, arg) => {
      let fVal = eval(f);
      let argVal = eval(arg);
      match fVal {
        TLam(param, body) => eval(subst(body, param, argVal)),
        _ => TApp(fVal, argVal)
      }
    }
  }

func showTerm(term: Term) -> string =
  match term {
    TVar(name) => name,
    TLam(param, body) => "(λ" ++ param ++ ". " ++ showTerm(body) ++ ")",
    TApp(f, arg) => "(" ++ showTerm(f) ++ " " ++ showTerm(arg) ++ ")"
  }

export func main() -> () ! {IO} {
  let expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"));
  let result = eval(expr);
  println(showTerm(result))
