-- Recursively filters a list based on a predicate function.
pure func filter(p: int -> bool, xs: [int]) -> [int] =
  match xs {
    [] => [],
    head :: tail =>
      if p(head) then head :: filter(p, tail)
      else filter(p, tail)
  }

