  match xs {
    [] => [],
    head :: tail => f(head) :: map(f, tail)
  }

-- Recursively computes the sum of a list of integers.
-- This is a left fold (foldl) with addition.
pure func sum(xs: [int]) -> int =
  match xs {
    [] => 0,
    head :: tail => head + sum(tail)
  }

