pure func merge(xs: [int], ys: [int]) -> [int] =
  match (xs, ys) {
    ([], y_list) => y_list,
    (x_list, []) => x_list,
    (x :: x_rest, y :: y_rest) =>
      if x <= y then x :: merge(x_rest, ys)
      else y :: merge(xs, y_rest)
  }

-- Splits a list into two halves
