pure func mergeSort(xs: [int]) -> [int] =
  if length(xs) <= 1 then xs
  else match split(xs) {
    (left, right) => {
      let sorted_left = mergeSort(left);
      let sorted_right = mergeSort(right);
      merge(sorted_left, sorted_right)
    }
  }

