import typing

class Some:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Some({repr(self.value)})"

    def __eq__(self, other):
        if isinstance(other, Some):
            return self.value == other.value
        return False

# The conceptual "Option type" is represented by either an instance of Some or the None singleton.
# For type hinting, we use typing.Optional[Some] to represent this union.
# The problematic line `Option = Some | None` from the previous attempt is removed
# as it was causing a TypeError when Python tried to evaluate the union at runtime
# in an environment where `|` for types is not supported for direct assignment.

def safeLast(lst: list) -> typing.Optional[Some]:
    if lst:
        return Some(lst[-1])
    else:
        return None

def flatMapOption(fn: typing.Callable[[typing.Any], typing.Optional[Some]], option: typing.Optional[Some]) -> typing.Optional[Some]:
    if isinstance(option, Some):
        return fn(option.value)
    else:
        return None

def safeHead(lst: list) -> typing.Optional[Some]:
    if lst:
        return Some(lst[0])
    else:
        return None

