def run_length_encode(chars):
    """Encode a list of characters using run-length encoding."""
    if not chars:
        return []

    encoded = []
    current_char = chars[0]
    count = 1

    for i in range(1, len(chars)):
        if chars[i] == current_char:
            count += 1
        else:
            encoded.append((count, current_char))
            current_char = chars[i]
            count = 1

    encoded.append((count, current_char))
    return encoded

def format_output(encoded):
    """Format the encoded result as a readable string."""
    result = "["
    for i, (count, char) in enumerate(encoded):
        if i > 0:
            result += ", "
        result += f"({count}, {char})"
    result += "]"
    return result

def main():
    input_list = ['a', 'a', 'a', 'b', 'b', 'c', 'c', 'c', 'c', 'a']
