import collections

class Idle(collections.namedtuple('Idle', ['floor'])):
    pass

class Moving(collections.namedtuple('Moving', ['current_floor', 'target_floor'])):
    pass

class DoorOpen(collections.namedtuple('DoorOpen', ['floor', 'timer'])):
    pass

class Call(collections.namedtuple('Call', ['target_floor'])):
    pass

class Tick(collections.namedtuple('Tick', [])):
    pass

class Arrive(collections.namedtuple('Arrive', [])):
    pass

def transition(state, event):
    # Idle state transitions
    if isinstance(state, Idle):
        if isinstance(event, Call):
            if event.target_floor == state.floor:
                return DoorOpen(state.floor, 3)
            else:
                return Moving(state.floor, event.target_floor)
        else: # Tick, Arrive
            return state

    # Moving state transitions
    elif isinstance(state, Moving):
        if isinstance(event, Tick):
            return state
        elif isinstance(event, Arrive):
            return DoorOpen(state.target_floor, 3)
        else: # Call
            return state

    # DoorOpen state transitions
    elif isinstance(state, DoorOpen):
        if isinstance(event, Tick):
            if state.timer > 1:
                return DoorOpen(state.floor, state.timer - 1)
            else:
                return Idle(state.floor)
        else: # Call, Arrive
            return state

    # Exhaustive handling - should not be reached with the current state types
    return state


def display(state):
    if isinstance(state, Idle):
        return f"IDLE @ floor {state.floor}"
    elif isinstance(state, Moving):
        return f"MOVING {state.current_floor} -> {state.target_floor}"
    elif isinstance(state, DoorOpen):
        return f"DOOR_OPEN @ floor {state.floor} ({state.timer}sec)"
    else:
        return "UNKNOWN STATE"

if __name__ == "__main__":
