    Node(left, v, right) => Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }

export func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(v) => fn(acc, v),
    Node(left, v, right) => {
      let leftResult = foldTree(fn, acc, left);
      let midResult = fn(leftResult, v);
      foldTree(fn, midResult, right)
    }
  }

export func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) => treeToList(left) ++ [v] ++ treeToList(right)
  }

export func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => 1 + (if treeDepth(left) > treeDepth(right) then treeDepth(left) else treeDepth(right))
  }

export func main() -> () ! {IO} {
  let tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)));

  let list1 = treeToList(tree);
  println(show(list1));

  let doubled = mapTree(\x. x * 2, tree);
  let list2 = treeToList(doubled);
  println(show(list2));

  let sum = foldTree(\acc x. acc + x, 0, tree);
  println(show(sum));

  let depth = treeDepth(tree);
  println(show(depth))
}

