import operator

class Leaf:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Leaf({self.value})"

class Node:
    def __init__(self, left, value, right):
        self.left = left
        self.value = value
        self.right = right

    def __repr__(self):
        return f"Node({self.left}, {self.value}, {self.right})"

def mapTree(fn, tree):
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )
    else:
        raise TypeError("Unknown tree type encountered in mapTree")

def foldTree(fn, acc, tree):
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        # In-order fold: left -> value -> right
        acc_left = foldTree(fn, acc, tree.left)
        acc_current = fn(acc_left, tree.value)
        acc_final = foldTree(fn, acc_current, tree.right)
        return acc_final
    else:
        raise TypeError("Unknown tree type encountered in foldTree")

def treeToList(tree):
    result = []
    if isinstance(tree, Leaf):
        result.append(tree.value)
    elif isinstance(tree, Node):
        result.extend(treeToList(tree.left))
        result.append(tree.value)
        result.extend(treeToList(tree.right))
    else:
        raise TypeError("Unknown tree type encountered in treeToList")
    return result

def treeDepth(tree):
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    else:
        raise TypeError("Unknown tree type encountered in treeDepth")

