#      / \ / \
#     1  3 5  7
test_tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))

# Print results
print(treeToList(test_tree))
print(treeToList(mapTree(double, test_tree)))
print(foldTree(add, 0, test_tree))
print(treeDepth(test_tree))

