from dataclasses import dataclass
from typing import List, Tuple, Optional, Union

@dataclass
class TVar:
    name: str

@dataclass
class TInt:
    pass

@dataclass
class TBool:
    pass

@dataclass
class TFunc:
    arg_type: Union['TVar', 'TInt', 'TBool', 'TFunc']
    result_type: Union['TVar', 'TInt', 'TBool', 'TFunc']

Type = Union[TVar, TInt, TBool, TFunc]
Substitution = List[Tuple[str, Type]]

def apply(subst: Substitution, t: Type) -> Type:
    if isinstance(t, TVar):
        for var_name, var_type in subst:
            if var_name == t.name:
                return apply(subst, var_type)
        return t
    elif isinstance(t, TInt):
        return t
    elif isinstance(t, TBool):
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg_type), apply(subst, t.result_type))
    else:
        return t

def unify(t1: Type, t2: Type) -> Optional[Substitution]:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        subst1 = unify(t1.arg_type, t2.arg_type)
        if subst1 is None:
            return None

        arg2_applied = apply(subst1, t2.arg_type)
        result1_applied = apply(subst1, t1.result_type)
        result2_applied = apply(subst1, t2.result_type)

        subst2 = unify(result1_applied, result2_applied)
        if subst2 is None:
            return None

        return subst1 + subst2
    else:
        return None

type1 = TFunc(TVar("a"), TInt())
type2 = TFunc(TBool(), TVar("b"))

result = unify(type1, type2)

if result is not None:
    for var_name, var_type in result:
        if isinstance(var_type, TInt):
            print(f"{var_name} = TInt")
        elif isinstance(var_type, TBool):
            print(f"{var_name} = TBool")
        elif isinstance(var_type, TFunc):
            print(f"{var_name} = TFunc(...)")
        elif isinstance(var_type, TVar):
            print(f"{var_name} = TVar({var_type.name})")
else:
    print("Unification failed")
